WITH filtered_suppliers AS (SELECT * FROM suppliers WHERE city IN ('Bangkok', 'Tokyo') OR country IN ('TH', 'SG')), summary AS (SELECT country, CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 2.6 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(rating) AS max_rating, COUNT(DISTINCT rating) AS unique_citys FROM filtered_suppliers GROUP BY country, CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 2.6 THEN 'mid' ELSE 'low' END) SELECT * FROM summary ORDER BY rating_bucket, unique_citys DESC, country LIMIT 1
